    @GameTest(template="empty",timeoutTicks=240) public static void blueprintFourRotationsHaveExactTwentySixSourcesAndWildcardTop(GameTestHelper h){new Fixture(h).run(f->{for(Direction side:Direction.Plane.HORIZONTAL){var parts=InfernalFurnaceFormation.parts(f.pos.offset(-1,-1,-1),side);h.assertTrue(parts.size()==26&&parts.stream().filter(p->p.id().equals("placeholder_brick")).count()==12&&parts.stream().filter(p->p.id().equals("placeholder_obsidian")).count()==12,"Blueprintsourcecounts changed:"+side);f.layout(side);f.block(f.pos.above(),Blocks.DIAMOND_BLOCK.defaultBlockState());var layout=InfernalFurnaceFormation.match(f.level,f.pos.above());h.assertTrue(layout!=null&&layout.anchor().equals(f.pos)&&layout.facing()==side,"Rotatedblueprint/nullwildcard mismatch:"+side);}});}
    @GameTest(template="empty",timeoutTicks=240) public static void shellDismantleRestoresPaidLavaBarsAndRemainingTwentyThreeMaterials(GameTestHelper h){new Fixture(h).run(f->{f.layout(Direction.NORTH);var context=f.use(f.pos.above(),Direction.NORTH);h.assertTrue(InfernalFurnaceFormation.use(context).consumesAction(),"Nativeformationfailed");var shell=InfernalFurnaceFormation.parts(f.pos.offset(-1,-1,-1),Direction.NORTH).stream().filter(p->p.id().equals("placeholder_brick")).findFirst().orElseThrow().pos();f.block(shell,Blocks.AIR.defaultBlockState());h.assertTrue(f.level.getBlockState(f.pos).is(Blocks.LAVA)&&f.level.getBlockState(f.pos.north()).is(Blocks.IRON_BARS),"Reversecorelava/outputbarsnotrestored");int materials=0;for(var part:InfernalFurnaceFormation.parts(f.pos.offset(-1,-1,-1),Direction.NORTH))if(part.id().startsWith("placeholder")&&!part.pos().equals(shell)){h.assertTrue(f.level.getBlockState(part.pos()).is(InfernalFurnacePlaceholderBlock.original(part.id())),"Paidmaterialdidn'trevert");materials++;}h.assertTrue(materials==23&&f.level.getBlockState(shell).isAir(),"Brokenmemberwasregrown/revertedtwice");});}
