    @GameTest(template="empty",timeoutTicks=240) public static void canceledDustFormationRestoresExactSourcesAndDoesNotDebit(GameTestHelper h){new Fixture(h).run(f->{f.layout(Direction.WEST);var context=f.use(f.pos.above(),Direction.WEST);var physical=context.getItemInHand();Consumer<BlockEvent.EntityMultiPlaceEvent> veto=e->{if(e.getEntity()==f.player)e.setCanceled(true);};MinecraftForge.EVENT_BUS.addListener(veto);try{h.assertTrue(!InfernalFurnaceFormation.use(context).consumesAction()&&physical.getCount()==1&&InfernalFurnaceFormation.match(f.level,f.pos)!=null&&f.level.getBlockEntity(f.pos)==null,"Canceleddustchangedpaidrecipe/source");}finally{MinecraftForge.EVENT_BUS.unregister(veto);}});}
