    @GameTest(template="empty",timeoutTicks=240) public static void missingLegacyFurnaceAndBellowsAcquireNativeTilesOnlyOnce(GameTestHelper h){new Fixture(h).run(f->{f.furnace();BlockPos bellowsPos=f.pos.east(3);f.block(bellowsPos,CatalogBlocks.block("bellows").defaultBlockState());var furnaceChunk=f.level.getChunkSource().getChunkNow(f.pos.getX()>>4,f.pos.getZ()>>4);var bellowsChunk=f.level.getChunkSource().getChunkNow(bellowsPos.getX()>>4,bellowsPos.getZ()>>4);h.assertTrue(furnaceChunk!=null&&bellowsChunk!=null,"Both native migration fixture chunks must already be loaded");f.level.removeBlockEntity(f.pos);f.level.removeBlockEntity(bellowsPos);LegacyInfernalDeviceMigration.repair(f.level,furnaceChunk);if(bellowsChunk!=furnaceChunk)LegacyInfernalDeviceMigration.repair(f.level,bellowsChunk);var furnace=furnaceChunk.getBlockEntity(f.pos,net.minecraft.world.level.chunk.LevelChunk.EntityCreationType.CHECK);var bellows=bellowsChunk.getBlockEntity(bellowsPos,net.minecraft.world.level.chunk.LevelChunk.EntityCreationType.CHECK);h.assertTrue(furnace instanceof InfernalFurnaceBlockEntity&&bellows instanceof BellowsBlockEntity,"MissinglegacydeviceBE notmigrated");LegacyInfernalDeviceMigration.repair(f.level,furnaceChunk);if(bellowsChunk!=furnaceChunk)LegacyInfernalDeviceMigration.repair(f.level,bellowsChunk);h.assertTrue(furnaceChunk.getBlockEntity(f.pos,net.minecraft.world.level.chunk.LevelChunk.EntityCreationType.CHECK)==furnace&&bellowsChunk.getBlockEntity(bellowsPos,net.minecraft.world.level.chunk.LevelChunk.EntityCreationType.CHECK)==bellows,"Migrationreplayednativeidentities");});}
    @GameTest(template="empty",timeoutTicks=240) public static void unpaidUnloadedOutputsAreNotForceLoaded(GameTestHelper h){new Fixture(h).run(f->{BlockPos far=new BlockPos(20000000,200,20000000);h.assertTrue(f.level.getChunkSource().getChunkNow(far.getX()>>4,far.getZ()>>4)==null,"Distantfixtureunexpectedlyloaded");var tag=new CompoundTag();var rows=new ListTag();var row=new CompoundTag();row.putLong("Pos",far.asLong());row.putByte("Face",(byte)Direction.NORTH.get3DDataValue());row.put("Stack",new ItemStack(Items.EMERALD,2).save(new CompoundTag()));rows.add(row);tag.put("Outputs",rows);var data=InfernalFurnaceOutputData.load(tag);data.tick(f.level);h.assertTrue(data.pendingItemCount(far)==2&&f.level.getChunkSource().getChunkNow(far.getX()>>4,far.getZ()>>4)==null,"Ledgerloaded distantchunk/lostunavailableoutput");h.assertTrue(InfernalFurnaceFormation.match(f.level,far)==null&&f.level.getChunkSource().getChunkNow(far.getX()>>4,far.getZ()>>4)==null,"Blueprintmatch force-loadedchunks");});}
